<template>
  <div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><TeacherClassSelector v-if="auth.role !== 'student' && !selectedClassId" :classes="classes" :loading="loading" title="Sổ điểm" description="Chọn một lớp để xem và quản lý kết quả học tập." feature-count-label="mục điểm" @select="selectClass" /><template v-else><div class="toolbar page-toolbar"><div v-if="auth.role !== 'student'" class="class-context"><strong>{{ selectedClassLabel }}</strong><button class="mini-button" @click="changeClass">Đổi lớp</button></div><select v-else v-model="selectedClassId" class="form-select" style="max-width:340px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><div class="toolbar-actions"><span class="cell-subtle">{{ gradebook?.items.length || 0 }} mục điểm</span><RouterLink v-if="auth.role !== 'student'" class="button secondary" to="/reports">Mở báo cáo</RouterLink></div></div><section v-if="editingItem" class="panel" style="margin-bottom:16px"><form class="inline-form" @submit.prevent="saveWeight"><div><strong>{{ editingItem.title }}</strong><span class="cell-subtle">Trọng số từ 0 đến 100</span></div><input v-model.number="weightForm" class="form-input" type="number" min="0" max="100" step="0.01" required /><button class="button primary" :disabled="weightBusy">{{ weightBusy ? 'Đang lưu…' : 'Lưu trọng số' }}</button><button type="button" class="mini-button" @click="editingItem = null">Đóng</button></form></section><div v-if="loading" class="loading-state">Đang tải sổ điểm…</div><section v-else-if="gradebook" class="panel"><div class="panel-heading"><h2>{{ auth.role === 'student' ? 'Điểm của bạn' : 'Sổ điểm' }}</h2><span>{{ gradebook.students.length }} người học</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th v-if="auth.role !== 'student'">Học viên</th><th v-for="item in gradebook.items" :key="item.gradeItemId">{{ item.title }}<span class="cell-subtle">{{ item.maxScore }} điểm · {{ item.weight }}</span><button v-if="auth.role !== 'student'" class="mini-button" @click="editWeight(item)">Sửa trọng số</button></th><th>Trung bình</th></tr></thead><tbody><tr v-for="student in visibleStudents" :key="student.studentId"><td v-if="auth.role !== 'student'"><span class="cell-primary">{{ student.studentId.slice(0, 8) }}</span></td><td v-for="item in gradebook.items" :key="item.gradeItemId"><span class="cell-primary">{{ score(student, item.gradeItemId) }}</span><span class="cell-subtle">{{ gradeStatus(student, item.gradeItemId) }}</span></td><td><strong>{{ student.finalScore ?? student.weightedAverage ?? student.average ?? '—' }}</strong></td></tr></tbody></table></div><div v-if="!visibleStudents.length" class="empty-state"><strong>Chưa có điểm</strong><span>Điểm sẽ xuất hiện sau khi giảng viên chấm và công bố.</span></div></section><div v-else class="panel empty-state"><strong>Chưa có dữ liệu sổ điểm</strong><span>Chọn lớp để tải sổ điểm theo quyền của bạn.</span></div></template></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import { useAuthStore } from '../../../shared/stores/auth'; import TeacherClassSelector from '../../../shared/ui/TeacherClassSelector.vue'; import { academicsApi, assessmentApi, gradingApi } from '../../../shared/api/client'; import type { Gradebook, GradebookItem, GradebookStudent, LearningClass } from '../../../shared/types'
const auth = useAuthStore(); const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const gradebook = ref<Gradebook | null>(null); const loading = ref(true); const error = ref(''); const editingItem = ref<GradebookItem | null>(null); const weightForm = ref(1); const weightBusy = ref(false); const selectedClassLabel = computed(() => { const item = classes.value.find(entry => entry.id === selectedClassId.value); return item ? `${item.code} · ${item.name}` : 'Lớp học' }); const visibleStudents = computed(() => auth.role === 'student' ? gradebook.value?.students.slice(0, 1) || [] : gradebook.value?.students || []); function selectClass(id: string) { selectedClassId.value = id }; function changeClass() { selectedClassId.value = '' }
function entries(student: GradebookStudent) { return student.entries || student.cells || [] }; function score(student: GradebookStudent, id: string) { return entries(student).find(item => item.gradeItemId === id)?.score ?? '—' }; function gradeStatus(student: GradebookStudent, id: string) { return entries(student).find(item => item.gradeItemId === id)?.status ?? 'Chưa có điểm công bố' }
async function load() { if (!selectedClassId.value) { gradebook.value = null; loading.value = false; return }; loading.value = true; try { gradebook.value = await assessmentApi.gradebook(selectedClassId.value, auth.role === 'student') } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được sổ điểm.') } finally { loading.value = false } }
function editWeight(item: GradebookItem) { editingItem.value = item; weightForm.value = Number(item.weight) }
async function saveWeight() { if (!editingItem.value) return; weightBusy.value = true; try { await gradingApi.updateGradeItem(editingItem.value.gradeItemId, weightForm.value); editingItem.value = null; await load() } catch (cause) { error.value = String((cause as Error)?.message || 'Không cập nhật được trọng số.') } finally { weightBusy.value = false } }
async function boot() { try { classes.value = await academicsApi.classes(); if (auth.role === 'student' && classes.value[0]) selectedClassId.value = classes.value[0].id; else loading.value = false } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được lớp học.'); loading.value = false } }
watch(selectedClassId, load); onMounted(boot)
</script>
